import './Experience.css';
import React from 'react';

function Experience() {

    function filterSelection(c) {
        var x, i;
        x = document.getElementsByClassName("column");
        if (c === "all") c = ""; // Show all items if "all" is selected
    
        // Loop through all elements and hide or show based on the filter
        for (i = 0; i < x.length; i++) {
            w3RemoveClass(x[i], "show");
            if (x[i].className.indexOf(c) > -1) {
                w3AddClass(x[i], "show");
            }
        }
    }
    

  return (
    <div className="Experience">
      <div className='experienceButtonContainer'>
        <button className='experienceButton' 
        onClick={() => filterSelection('Work')}>Work</button>
        <button className='experienceButton'
        onClick={() => filterSelection('Education')}>Education</button>
      </div>

        <div className='ExperienceSection'>
        
        <div className='Work'>

        </div>

        <div className='Education'>

        </div>
    
    
        </div> 


    </div>
  );
}

export default Experience;
